import{_ as a,o as t,c as o,a0 as n}from"./chunks/framework.BFac62L4.js";const p=JSON.parse('{"title":"Multi-factor authentication","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/configuration-server-core-mfa.md","filePath":"guide/deployment/configuration-server-core-mfa.md"}'),i={name:"guide/deployment/configuration-server-core-mfa.md"};function r(c,e,s,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="multi-factor-authentication" tabindex="-1">Multi-factor authentication <a class="header-anchor" href="#multi-factor-authentication" aria-label="Permalink to &quot;Multi-factor authentication&quot;">​</a></h1><p>Authup supports TOTP, recovery codes, email codes, and WebAuthn credentials as second factors. Enable the feature with <code>mfaEnabled</code> (<code>MFA_ENABLED</code>) and require interactive enrollment for every local user with <code>mfaRequired</code> (<code>MFA_REQUIRED</code>). <code>mfaRequired</code> can only be enabled together with <code>mfaEnabled</code>.</p><p>Users enroll and remove their authenticators themselves on the <a href="./account-console.html">account console</a> (<code>&lt;publicUrl&gt;/console/account/authenticators</code>), which is served by <code>server-core</code> and therefore also available in headless deployments. Inline enrollment during login rides the hosted <code>/authorize</code> page (below).</p><h2 id="enforcement-model" tabindex="-1">Enforcement model <a class="header-anchor" href="#enforcement-model" aria-label="Permalink to &quot;Enforcement model&quot;">​</a></h2><p>With MFA enabled, a local user who has any confirmed authenticator must complete a second-factor challenge during password login and before authorization-code issuance. <code>mfaRequired</code> additionally routes a device-less user through inline enrollment on the hosted <code>/authorize</code> page.</p><p>The following boundaries are intentional:</p><ul><li><p>A federated identity-provider login is authenticated by the external provider, which is where MFA is configured and enforced for it. Authup does not stack a local factor on top, and <code>mfaRequired</code> does not force local enrollment on those users. The route is opt-in: a first federated login provisions a NEW user, and an external identity reaches an existing account only when that account&#39;s owner links it while signed in. Configure and enforce MFA at the upstream provider, and verify that it did with the provider&#39;s <code>requiredAmr</code> / <code>requiredAcr</code> allow-lists, which are unset by default so the trust is otherwise unchecked (see <a href="./../user/identity-providers.html#verifying-what-the-provider-did">identity providers</a>). The one exception is an application that requests <code>acr_values=urn:authup:mfa</code>: it asked for a proof, and a local factor the user holds is the only one Authup can produce, so the hosted page challenges it before issuing that application&#39;s authorization code.</p></li><li><p>Setting <code>mfaEnabled</code> to <code>false</code> disables both local MFA configuration and enforcement, including for users who already have confirmed authenticators. Authenticator rows are retained and become active again when MFA is re-enabled. Treat disabling this option as an authentication-policy downgrade.</p></li><li><p>The direct resource-owner password grant permits a device-less user to obtain the initial session even when <code>mfaRequired</code> is enabled. The hosted login uses that same bootstrap session to reach inline enrollment, which cannot be completed inside a single password-grant request. Restrict the <code>password</code> grant with each client&#39;s <code>grantTypes</code> allowlist and use the authorization code flow when enrollment must be enforced before issuing an application token.</p></li></ul><h2 id="cache-availability" tabindex="-1">Cache availability <a class="header-anchor" href="#cache-availability" aria-label="Permalink to &quot;Cache availability&quot;">​</a></h2><p>MFA verification uses a per-user cache lock to serialize factor consumption. The lock has an owner token and is renewed while verification is in progress; renewal and release are conditional on that token so an expired owner cannot extend or delete a successor&#39;s lock.</p><p>Verification fails closed when the cache or lock is unavailable. This applies even to TOTP and recovery codes, whose counters and <code>used_at</code> stamps provide a persistent replay backstop, because allowing concurrent read-verify-save sections during an outage could accept the same factor twice. A configured Redis deployment should therefore include Redis availability in the login-path service-level objective.</p><p>The same fail-closed posture applies to the per-account attempt throttle that guards enrollment confirmation and challenge-code delivery: when the throttle counter cannot be read, those endpoints degrade to a retry-able throttled response (HTTP 429) rather than surfacing the outage as an internal 500.</p><h2 id="related-settings" tabindex="-1">Related settings <a class="header-anchor" href="#related-settings" aria-label="Permalink to &quot;Related settings&quot;">​</a></h2><ul><li><code>mfaFreshnessMaxAge</code> (<code>MFA_FRESHNESS_MAX_AGE</code>) controls how long a session&#39;s MFA proof satisfies an explicit <code>acr_values=urn:authup:mfa</code> step-up request.</li><li><code>mfaTicketMaxAge</code> (<code>MFA_TICKET_MAX_AGE</code>) controls the short-lived pending login ticket used by email and WebAuthn challenges.</li><li>Email authentication requires an SMTP transport. WebAuthn uses <code>publicUrl</code> as its relying-party origin.</li></ul><p>See the <a href="./configuration-server-core.html">server configuration reference</a> for all configuration formats and defaults.</p>',14)])])}const f=a(i,[["render",r]]);export{p as __pageData,f as default};
